INSERT INTO `battle_pet_ability_locale` (`ID`, `locale`, `Name_lang`, `Description_lang`, `VerifiedBuild`) VALUES
(2435, 'koKR', '마나 불꽃', '직접 피해를 입을 때마다 [StandardDamage(1,1,2436)]의 [School()] 피해를 되돌려줍니다.\n\n[duration(1,1)]라운드 동안 지속됩니다.', 56647),
(2378, 'koKR', '빛줄기', '|cffffffff적중률|r [StandardAccuracy(1,1)]\n\n상대 팀의 현재 애완동물에게 [StandardDamage(1,1)]의 [School()] 피해를 입히고, 대기 중인 적 애완동물에게도 [StandardDamage(1,2)]의 [School()] 피해를 입힙니다. 모든 아군의 생명력을 [StandardHealing(1,1)]만큼 회복시킵니다.', 56647),
(1369, 'koKR', '날카로운 독침', '|cffffffff적중률|r [StandardAccuracy(1,1)]\n\n즉시 [StandardDamage(1,1)]의 [School()] 피해를 입히고, 20%의 확률로 대상을 |cFF1EFF00중독|r시켜 추가로 [duration(1,2)]라운드 동안 매 라운드마다 [StandardDamage(1,1,379)]의 [School(379)] 피해를 입힙니다.', 56647);
INSERT INTO `battle_pet_species_locale` (`ID`, `locale`, `Description_lang`, `SourceText_lang`, `VerifiedBuild`) VALUES
(3265, 'koKR', '악취가 진동하는 머스켄을 가능한 한 미화하면 이런 모습일 겁니다.', '|cFFFFD200업적:|r 소소하지만 확실한 행복', 56647),
(4517, 'koKR', '꿈과 소원이 이루어진 기적 속에서 밀랍심지는 깨어났고, 코볼트 머리에서 내려와 자신의 길을 찾아 나섰습니다.', '|cFFFFD200업적:|r 카즈 알가르 사파리|n', 56647),
(4581, 'koKR', '', '|cFFFFD200업적: |r용사의 원정: 내부 전쟁|n|cFFFFD200범주: |r세계', 56647),
(4543, 'koKR', '이 어둠의 생명체는 핀리 므르글턴 경이 탐험 중 우연히 발견한 이후로 계속 그를 따라다녔습니다. 이 끈질긴 친구에게 제법 정이 붙은 핀리 경도 쉽게 헤어질 생각이 없답니다.', '|cFFFFD200상인: |r핀리 므르글턴 경|n|cFFFFD200지역: |r도르노갈|n|cFFFFD200가격: |r10000|Hcurrency:2803|h|TInterface\\ICONS\\INV_Misc_ElvenCoins.blp:0|t|h', 56647);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(268268, 'koKR', '', '아닐 것 같단 예감이 강하게 들지만.', 56647),
(259733, 'koKR', '', '다음은 너다.', 56647),
(260378, 'koKR', '', '고마워요, 아버지. 그때가 너무 빨리 오지 않기를 빌죠.', 56647),
(260375, 'koKR', '설령 내가 세상을 떠난다 한들, 나는 꿈도 꿀 수 없는 기품과 힘으로 선정을 펼치겠지.', '', 56647),
(260374, 'koKR', '하지만 넌 이제 내가 필요 없겠구나. 강인해진 모습을 보니 내가 다 뿌듯해.', '', 56647),
(260371, 'koKR', '난 너희를 보호하고 싶었다. 그마저도 잘 못 했지. 지금도 우린 심각한 위험에 처해 있지 않느냐.', '', 56647),
(260345, 'koKR', '', '완전히 용서할 수는 없지만 이해는 할 수 있게 됐죠.', 56647),
(260336, 'koKR', '', '하지만 나이가 들고, 다그란이 성장하고, 통치에 관해 배우면 배울수록...', 56647),
(260333, 'koKR', '', '아버지가 어린 저와... 다그란의 아버지에게 한 행동을 갖고 따질 마음이 없잖아 있었어요.', 56647),
(260303, 'koKR', '이런 견부 아래에서도 넌 보란 듯이 영민한 정신과 다그란이 올곧게 자랄 수 있게 해줄 심성을 갖춘 통치자로 성장했다.', '', 56647),
(260294, 'koKR', '아니야. 입이 열 개라도 할 말이 없구나. 나 스스로 떳떳하지 못한 일을 꽤 저질렀으니까.', '', 56647),
(260287, 'koKR', '', '뭐라고요? 흠. 아버지 입으로 그런 말을 듣게 될 줄은 몰랐네요. 어디 편찮으신 거예요?', 56647),
(260283, 'koKR', '그냥 이 말을 하고 싶었다... 네가 자랑스럽구나.', '', 56647),
(260266, 'koKR', '그건 안다. 내가... 이 기계들로 했어도 못하면 못 했지, 더 잘하진 않았을 거야.', '', 56647),
(260265, 'koKR', '', '걱정 마세요, 아버지. 전부 제 통제하에 있으니.', 56647),
(260264, 'koKR', '모이라, 잠깐 얘기 좀 할 수 있겠느냐?', '', 56647),
(263779, 'koKR', '감사해요, 어머니. 함께 무엇을 발견하게 될지... 기대된다는 말씀 말고는 달리 드릴 말씀이 없네요.', '', 56647),
(263778, 'koKR', '', '오직 너니까 나도 선뜻 도시를 추락시키고, 새로운 종족을 만나고, 어두운 구멍에 함께 뛰어드는 거다.', 56647),
(263777, 'koKR', '', '넌 우리 종족의 미래이고, 이 세상에 공헌할 수 있는 것이 많다. 누가 뭐라고 해도 알 바 아니야.', 56647),
(263776, 'koKR', '', '몇 시간? 며칠이라도 들어줄 수 있단다. 피붙이라 마냥 객관적이라고 하진 못해도, 어쨌든 넌 훌륭한 심성을 지녔다.', 56647),
(263775, 'koKR', '정말요? 그러다 질문이라도 하셨을 때... 제가 주체 못 하면 몇 시간이고 이야기를 늘어놓을 수도 있는데...', '', 56647),
(263774, 'koKR', '', '넌 역사와 문화에 대한 식견이 깊지. 난 이미 널 내 조언가로 여기고 있단다.', 56647),
(263773, 'koKR', '', '잘됐구나. 널 위험에 빠뜨리고 싶진 않지만, 그래도 모험이 체질에 맞는 것 같아 다행이야.', 56647),
(263772, 'koKR', '아뇨, 어머니. 전 여기서 많은 걸 배웠어요. 세상이 너무 새롭고... 동시에 오래된 것처럼 느껴지네요.', '', 56647),
(263771, 'koKR', '', '다그란, 내려갈 준비는 됐겠지? 굳이 안 가도 된다. 기록 보관소에 남고 싶으면 그렇게 해.', 56647),
(260591, 'koKR', '', '도르노갈은 수호자를 잃었고, 난... 친구를 잃었소.', 56647),
(260588, 'koKR', '', '우리 둘이 마냥 고집을 부리지 않았다면 그가 그렇게 되지 않았을지도 모른다는 생각이 드는구려.', 56647),
(260584, 'koKR', '', '저 혼자 도르노갈이란 멍에를 지게 둔 채 떠나버린 날 절대 용서하지 않을 거라 생각했건만, 결국 끝에 가서는...', 56647),
(260582, 'koKR', '', '논리 회로는 나를 티탄에게 등 돌리는 방향으로 이끌었소. 반대로 바엘그림은 어느 때보다도 더 티탄을 찾게 됐지.', 56647),
(260580, 'koKR', '', '난 절망이 동족을 어떻게 만드는지 똑똑히 보았소. 바엘그림도 봤지.', 56647),
(260579, 'koKR', '', '그러다 모든 게... 무너지기 시작했다오. 중심로, 기록 보관소... 절망의 시대가 도래했고, 우린 조각보를 만들듯 하나 둘 기워 붙였지.', 56647),
(260578, 'koKR', '', '도르노갈은 우리 둘 모두가 필요했지.', 56647),
(260576, 'koKR', '', '동시에 우린 멍에를 쓴 두 숫양처럼 함께 나아갔소. 바엘그림은 폭풍떼까마귀를, 나는 채석장과 가열로를.', 56647),
(260573, 'koKR', '', '우린 자신의 업적과 영예를 서로 비교했소. 티탄들은 누구를 더 총애할지를 두고 따졌지.', 56647),
(260566, 'koKR', '', '바엘그림과 난 경쟁 관계였소. 둘 다 같은 시기에 지기의 직위를 받았지.', 56647),
(276521, 'koKR', '육중한 보관함이나 풍요로운 금고, 구렁의 종료 지점에 있는 숨겨진 상자를 열면 진행도가 오르고 보상을 얻을 수 있답니다.\n\n높은 난이도의 구렁일수록 진행도를 더 많이 얻죠!', '', 56647),
(264632, 'koKR', '', '하하! 아하하!', 56647),
(263040, 'koKR', '이 나무 정말 굉장하네요! 처음에는 약간 시들했는데, 그 게가 나타나기 무섭게 나뭇잎에 색이 좀 돌아왔어요. 별일이 다 있죠?\n\n저 게를 좀 더 데려오면 나무가 기운을 차릴지도 모르겠네요. 게들도 나무를 좋아하는 것 같은데!', '이 나무 정말 굉장하네요! 처음에는 약간 시들했는데, 그 게가 나타나기 무섭게 나뭇잎에 색이 좀 돌아왔어요. 별일이 다 있죠?\n\n저 게를 좀 더 데려오면 나무가 기운을 차릴지도 모르겠네요. 게들도 나무를 좋아하는 것 같은데!', 56647),
(263507, 'koKR', '알 수 없는 이상 현상이 감지되었습니다. 각성 정화 체계를 가동합니다.', '', 56647),
(258213, 'koKR', '이 차원문을 타고 카즈 알가르로 내려가시오. 탈출한 이들을 도와야 하오.', '', 56647),
(266134, 'koKR', '알았어요, 브란 삼촌! 제가 싸워볼까요?', '', 56647),
(253394, 'koKR', '벨한 공작님이 잘 해결해 주실 거예요. 공작님은 훌륭한 지도자니까요! \n\n사실 벨한의 추락지에서 병사들을 거의 잃지 않은 것도 공작님이 잘 이끌어 주셨기 덕분이라고요.', '벨한 공작님이 잘 해결해 주실 거예요. 공작님은 훌륭한 지도자니까요! \n\n사실 벨한의 추락지에서 병사들을 거의 잃지 않은 것도 공작님이 잘 이끌어 주셨기 덕분이라고요.', 56647),
(268948, 'koKR', '', '<즐거운 웃음소리>', 56647),
(268647, 'koKR', '', '전쟁 골렘이 활성화됐고, 생산도 재개됐어요!', 56647),
(265314, 'koKR', '', '시설이 재가동됐어요!', 56647),
(265313, 'koKR', '다들 짐 싸라! 안 되는 건 빨리 손 털어야 해...', '', 56647),
(265081, 'koKR', '', '승천자를 하나라도 그렇게 다룰 수 있다는 건...', 56647),
(265078, 'koKR', '', '눈 하나 깜짝 않고 이테키의 정신을 지배했어.', 56647),
(265077, 'koKR', '', '당장 나가게!', 56647),
(263478, 'koKR', '', '완성되었다.', 56647),
(263476, 'koKR', '', '네 승천은...', 56647),
(260586, 'koKR', '', '지금이야, 지지!', 56647),
(260581, 'koKR', '', '그거 알아? 네 말대로 했어.', 56647),
(260577, 'koKR', '좀 더 큰 친구들을 데려오지 그랬어.', '', 56647),
(261892, 'koKR', '', '아직 할 일은 많아요.', 56647),
(261891, 'koKR', '이제 뭘 하면 되죠, 루프셀라?', '', 56647),
(261890, 'koKR', '', '저 친구들이 스스로의 자유 의지로 우릴 돕기로 한 거예요.', 56647),
(261889, 'koKR', '', '저뿐만이 아니에요. 저들의 부름도 들은 거죠.', 56647),
(261888, 'koKR', '잘했네. 폭풍떼까마귀가 자네의 부름에 응했군.', '', 56647),
(261884, 'koKR', '부르면 응할 걸세.', '', 56647),
(261883, 'koKR', '루프셀라, 폭풍떼까마귀는 자네의 뜻을 알고 있네. 집중하게.', '', 56647),
(261881, 'koKR', '그 친구도 티탄을 거스르는데, 당신도 할 수 있어요!', '', 56647),
(261880, 'koKR', '바엘그림은 스스로 폭풍떼까마귀를 소환했습니다.', '', 56647),
(261878, 'koKR', '', '못 하겠어요... 맙소사...', 56647),
(263833, 'koKR', '', '<신음 소리>', 56647),
(261968, 'koKR', '해방자!', '', 56647),
(261967, 'koKR', '나, 도르노갈의 의회지기가 선언한다. 우리 모두...', '', 56647),
(261966, 'koKR', '누가 이 영광에 동참하겠소?', '', 56647),
(261958, 'koKR', '칙령이 쓰인 바로 그 장소에서.', '', 56647),
(261957, 'koKR', '잘됐군. 모든 게 시작된 이곳에서 하면 딱 어울릴 테니 말이오.', '', 56647),
(261956, 'koKR', '', '그러기 위해서는 칙령을 영원히 포기해야 할 터.', 56647),
(261955, 'koKR', '', '그렇소. 새로운 동맹을 도와야 하오.', 56647),
(261954, 'koKR', '그럼 동의한 거요?', '', 56647),
(252684, 'koKR', '예? 절 아십니까? \n\n모른다고요? 다행이네요. 기억이 예전 같지 않아서.\n\n전 해방자들의 준비 장소인 애도의 오름길의 마지막 관리인 코르그란입니다.\n\n주기를 타파하고 본인이 선택한 해방자로서 기억되고자 하는 분들이 이곳을 찾죠.\n\n저희처럼 정지라는 개념이 존재하는 종족이면 모를까, 그게 아니면 제가 도와드릴 일이 있을지 모르겠군요.', '', 56647),
(261480, 'koKR', '이 새 고서들 보셨어요, 브란 삼촌? 드렌덴의 도서관에서 온 건가 봐요.', '', 56647),
(259252, 'koKR', '아! 안녕하세요. 브란 삼촌과 이야기하러 오셨나요?', '', 56647),
(251198, 'koKR', '브란 삼촌하고 바로 따라갈게요. 전 배울 준비가 됐거든요!', '', 56647),
(261676, 'koKR', '', '반갑습니다, 영웅님. 사실 저도 카즈 알가르가 제법 기대됩니다. 탐험할 곳이 넘쳐나겠죠!', 56647),
(275557, 'koKR', '', '그림 바톨은 사실 용들에게 그리 좋은 추억이 있는 곳이 아니라, 저도 될 수 있으면 생각을 안 하려고 해요.\n\n근데 용사님은 악독한 적을 쓰러뜨리고 보물을 손에 넣으러 갈 생각이죠? 그렇다면 무용담을 꼭 듣고 싶네요.\n\n시간의 길에서 황혼의 고원으로 통하는 차원문을 사용하세요. 서쪽으로 가다 보면 산악 지대에서 입구를 찾으실 수 있을 거예요.', 56647),
(275556, 'koKR', '', '당연한 얘기지만 보랄러스로 가야 해요. 무역풍 시장 아래 부둣가를 살펴보세요.\n\n호드의 일원이라면 얘기가 좀 달라지지만요. 약탈의 항구에서 훨씬 안전하게 입장할 수 있답니다.\n\n시간의 길에서 티라가드 해협으로 통하는 차원문을 통과한 다음, 북쪽으로 향하세요. 어디든 먼저 공격받을 일 없는 마을로 가면 돼요.', 56647),
(275555, 'koKR', '', '\'상흔\'이라. 참 재밌는 단어 같아요. 어딘가로 가기 전에 상흔을 남길 때도, 지나간 길에 상흔을 남기기도 하잖아요?\n\n<잠시 말을 멈추고 당신의 반응을 살피는 린도르미>\n\n아무튼 시간의 길에서 승천의 보루로 통하는 차원문에 들어간 다음, 남서쪽으로 향하세요. 용기의 사원에서 아직 완전히 파괴되지 않은 일대를 살펴보면 입구가 있을 거예요.', 56647),
(275554, 'koKR', '', '티르너 사이드는 아차 하는 사이에 길 잃기 딱 좋은 곳이죠. 심지어 가는 길에도 미아가 될 수 있다니까요?\n\n시간의 길에서 몽환숲으로 통하는 차원문에 들어가세요. 그런 다음 서쪽으로 가면 되는데, 뿌리 사이에 잘 감춰진 입구를 찾으면 된답니다.', 56647),
(269791, 'koKR', '\"...전기가 흐르는 날개를 펄럭이며 왔네.\"', '', 56647),
(269790, 'koKR', '', '\"...전기가 흐르는 날개를 펄럭이며 왔네.\"', 56647),
(268067, 'koKR', '믿어지세요, $n 님? 여기에 묻혀있을 모든 역사를 생각해보세요!', '', 56647),
(266394, 'koKR', '이방인이 견딜 수 있다면 우리도 그 정도는 해야지. 황제 폐하께서는 우리가 적의 한계를 뛰어넘기를 바라신다.', '', 56647),
(266392, 'koKR', '신성한 불꽃이 우리를 지탱해 줄 거다, 동생아. 이교도들이 코비스의 분노를 불러일으키게 놔둬라. 우린 무방비한 측면을 치면 그만이다.', '', 56647),
(266390, 'koKR', '제 친구 시베스탄을 용서하십시오. 당신의 도움이 없었다면 여기까지 오지 못했을 겁니다.', '제 친구 시베스탄을 용서하십시오. 당신의 도움이 없었다면 여기까지 오지 못했을 겁니다.', 56647),
(266389, 'koKR', '훈련을 아주 잘 받았구나, 동생아. 이방인이 보고 배워도 되겠어.', '', 56647),
(261758, 'koKR', '<당신을 바라보는 안두인>\n\n$n 님. 늘 그렇듯이 정말 큰 도움이 됐습니다. 대체 비결이 뭐죠? \n\n어둠땅을 다녀온 이후로, 그게...\n\n고민이 많습니다.', '', 56647),
(261247, 'koKR', '<당신을 바라보는 안두인>\n\n$n 님. 늘 그렇듯이 정말 큰 도움이 됐습니다. 대체 비결이 뭐죠? \n\n어떻게 절 계속 봐주실 수 있는 건가요? 제가 당신에게... 그런 짓을 하려고 했는데. \n\n당신에게 칼끝을 들이밀었잖습니까.', '', 56647),
(260534, 'koKR', '그게 언제쯤인가요?', '', 56647),
(260468, 'koKR', '도르노갈은 언제부터 이곳에 있었나요?', '', 56647),
(260045, 'koKR', '예?', '', 56647),
(259965, 'koKR', '다시 일하러 가야겠군요... 안 할 수도 있지만.', '', 56647),
(258826, 'koKR', '안녕하세요! 보물 사냥에 관심이 있으신가요? 물론 그렇겠죠. \n\n이 동굴에는 제게 부족한 물... 아니, 다양한 물건이 숨겨져 있어요! 누구든 전부 챙겨 먼저 가져오는 사람에게 보물을 줄 겁니다!\n\n보물을 찾는 데 도움이 되도록 수영 속도를 높여주는 수정도 드리죠. 이런 밑지는 장사가 어디 또 있겠어요!', '', 56647),
(258555, 'koKR', '', '<잿불맥주를 한 모금 마신 뒤 당신을 올려다보는 보크그레트>\n\n액체 오팔을 찾는 데는 시간이 좀 걸립니다, 소중한 친구.\n\n시장 곳곳에 심어둔 제 첩자들이 액체 오팔을 찾는 동안, 수완을 좀 발휘해 주시죠.', 56647),
(256097, 'koKR', '', '안녕하세요! 만나서 반가워요!\n\n전 란난 님에게 배속된 알가르 원정대 훈련생 타레사라고 합니다. 여기 오게 되어 정말 기쁩니다. \n\n비록... 일이 이렇게 되긴 했지만요. \n\n전 티탄 기술에 관심이 많아요. 특히 란난 님과 투베로스는, 란난 님 표현을 빌려서... \"이것저것\" 다루는 데 정평이 나 있죠. 꼭 가까이서 보고 싶더라고요!\n\n그리고 그렇게 될 것 같고요! 그 과정에서 도시가 추락하긴 했지만...', 56647),
(266645, 'koKR', '브란? 지금쯤 다른 탐험가하고 어딘가에 있겠지. \n\n서두르지, 용사. 아제로스의 상처가 도움을 요청하는 소리가 들리는군.', '', 56647),
(266491, 'koKR', '', '넌 착한 코볼트 친구야, $n. 고마워.', 56647),
(254492, 'koKR', '잘 지냈나요, 친구?', '잘 지냈나요, 친구?', 56647),
(252740, 'koKR', '숨어서 떨어라, 잡것들아. 승천의 날을 방해하는 건 용납하지 않겠다.', '숨어서 떨어라, 잡것들아. 승천의 날을 방해하는 건 용납하지 않겠다.', 56647),
(251935, 'koKR', '대화는 짧게 끊어야 합니다. 공기 중에 독이 너무 많아요.\n\n땅울림 신발을 가져가세요. 망가진 공기 정화기를 다시 활성화하는 데 쓸 수 있습니다. 코볼트 시체에서 톱니바퀴를 입수한 다음, 수력작업장을 구해주셨으면 합니다.\n\n가세요.', '', 56647),
(261702, 'koKR', '', '이제 우리가 어떤 존재인지 알아가야 해요.', 56647),
(261700, 'koKR', '', '아제로스는 성장하고 있으며, 우리도 함께 성장해야 합니다.', 56647),
(261701, 'koKR', '', '변화의 부름을 받아들여야 합니다.', 56647),
(261699, 'koKR', '', '경직된 전통을 좇다 되려 파멸할 뻔했죠.', 56647),
(261696, 'koKR', '', '마그니의 희생이 있기 전, 우리 토석인은 타고난 목적에 속박되어 있었습니다.', 56647),
(252793, 'koKR', 'The Weaver bids you welcome.', '방직공께서 너희를 환영하신다.', 56647),
(252791, 'koKR', 'Scurry on, little scarab!', '빨리 움직여! 꼬마 딱정벌레!', 56647),
(256695, 'koKR', '', '네 반역을 덮으려는 속셈이겠지! 저것들을 분쇄한 다음에는 네 수급을 받아 가마.', 56647),
(256694, 'koKR', '안수레크 여왕님의 이름으로 반란군을 진압하겠다.', '', 56647),
(256691, 'koKR', '네가 드러낼 것은 단 하나, 네놈의 약점뿐이다.', '', 56647),
(256690, 'koKR', '', '역도들이 여기 있다! 모조리 해치운 다음에는 궁정에 숨은 놈들을 솎아낼 테다.', 56647),
(266867, 'koKR', '뭐라도 찾으면 여기서 가져가. 난 손을 완전히 털 생각이거든.', '뭐라도 찾으면 여기서 가져가. 난 손을 완전히 털 생각이거든.', 56647),
(260896, 'koKR', '', '날카로운 그림자로 꿰뚫어 주마.', 56647),
(260892, 'koKR', '', '끈적한 소용돌이에 휘말려라.', 56647),
(260891, 'koKR', '', '점성 폭발.', 56647),
(260875, 'koKR', '', '발버둥 쳐봤자 소용없다.', 56647),
(260874, 'koKR', '', '느려져라.', 56647),
(260838, 'koKR', '무리는 먹이를 먹어야 하는 법.', '', 56647),
(260837, 'koKR', '날뛰어 주마.', '', 56647),
(260836, 'koKR', '이 맹공도 받아봐라!', '', 56647),
(260835, 'koKR', '학살이 몰아친다.', '', 56647),
(260834, 'koKR', '막을 테면 막아봐라.', '', 56647),
(260822, 'koKR', '', '목숨을 끊어주마!', 56647),
(260821, 'koKR', '너희 해골을 가져가겠다!', '', 56647),
(261912, 'koKR', '퇴각하라, 병사들이여!', '', 56647),
(254365, 'koKR', '', '다그란이 한 번 관심을 가지면 무슨 수를 써도 막을 수가 없죠? \n\n말했다시피 탤로크는 중요한 광산 기지예요. 기름칠이 잘된 기계처럼 운영이 원활한 것으로 유명하죠. 제가 그곳 현장감독인 콜 브룬크래그와 오랫동안 알고 지내기도 했고요. 마지막으로 얘기를 나눈 지는 좀 됐지만요.\n\n광석 생산이 중단된 이유를 알아야겠어요... 고위 대변자는 제가 답을 찾지 못하길 바라고 있겠지만요. 아마 고위 대변자도 조사관을 보내긴 했을 거에요. 그래도 우리끼리 알아보죠.', 56647),
(271002, 'koKR', 'AR-938 구역 지상의 토석인은 최근 고난을 겪었습니다.\n\n이방인이 도른의 섬에 추락한 이후 요새 도르노갈이 네루비안의 공격을 받았습니다. 이방인과 폭풍기수들이 침략자들을 몰아내긴 했으나, 중심로는 이미 극심한 손상을 입은 뒤였습니다.\n\n과거 돌매듭으로 불렸던 토석인 집단 해방자와 아직 티탄에게 충성하는 서약신도는 이방인의 도움을 받아 지상을 지키기 위해 단결을 이루었고, 네루비안을 몰아내고 중심로를 복구하는 작업에 착수했습니다.\n\n이 사건의 흐름 속에서 폭풍기수는 폭풍지기 바엘그림이 전사하는 등 막대한 피해를 보았습니다. 그렇지만 군다가즈와 기계 대변자에게 통하는 중심로를 복구하는 성과 또한 있었습니다. \n\n중심로 전체 복구 작업은 아직 진행 중입니다.', '', 56647),
(270198, 'koKR', '변신소 막일꾼이 당신의 페로몬을 감지하고는 비켜섭니다.', '', 56647),
(266936, 'koKR', '', '당신과 투랄리온은 닮은 구석이 있어요. 전쟁터에선 용장, 마음 문제에선 숙맥.', 56647),
(265279, 'koKR', '이러다 전황이 뒤집히겠군!', '', 56647),
(265155, 'koKR', '', '당신의 생사는 그리 중요하지 않아요.', 56647),
(263196, 'koKR', '', '고위 대변자는 아득히 먼 옛날부터 우릴 이끌어 왔지만... 이젠 우리의 일원이 아닙니다.', 56647),
(262604, 'koKR', '', '지진 프로토콜 가동.', 56647),
(262333, 'koKR', '저 작은 버섯은 밟으면 통통 튈 것 같은데요.', '', 56647),
(261918, 'koKR', '', '침입자? 우리가 하늘에서 떨어져 목숨 걸고 싸우는 걸 봤잖아!', 56647),
(259785, 'koKR', '이제 저걸 없애야 합니다. 코비스가 미끼를 앞에 내세워 붙잡아 두고 있는 것 같네요.', '', 56647),
(259762, 'koKR', '', '밤에 굴복해라.', 56647),
(256027, 'koKR', '', '그야 당신이 계속 치유사를 무시했으니까요! 눈앞에 호박이 넝쿨째 굴러들어 왔는데 어떻게 무시하겠어요?', 56647),
(256024, 'koKR', '그러잖아도 저 기사한테 보병을 먹히지 않고 전진시킬 방법을 궁리하고 있었습니다. 기사를 개활지에 내놓고 있었군요, 페어린? 위험하게.', '', 56647),
(255118, 'koKR', '숨이 멎을 듯 아름다운 도시입니다. 아라시가 단기간에 이런 장소를 건설하다니, 정말 놀랍군요. \n\n생각해 보면 이 도시가 세워질 동안 우리는 군단과 싸우고, 4차 대전쟁을 치르고, 또... \n\n뭐. 아무튼 경치가 대단하네요.', '', 56647),
(254822, 'koKR', '좋은 질문이에요, $r 친구. 전 깨우는 자랍니다. 오래된 장소나 새로이 각성한 장소에 들어가 전체적으로 제대로 작동하는지 확인하는 게 제 의무죠. 울리는 심연은 말하자면 잠들어 있는 가공할 거인과도 같습니다. 전 그런 거인을 보살피는 사람이고요!\n\n의식에 집중할 동안 보호해 주세요. 기계의 마력도 가능한 한 많이 흡수하시고요! 충분히 마력을 모으면 끝까지 살아남을 수 있을 겁니다...', '', 56647),
(268527, 'koKR', '당신만 그런 게 아니오, 정무관. 저 모습의 벨레다르는 비애와 갈등의 징조라오.', '', 56647),
(267619, 'koKR', '그리고 거기서 찾은 우편은 당신과 크랄라, 파랑을 위해 남겨둘게요.', '', 56647),
(266121, 'koKR', '<다그란이 코볼트와 밀랍이 어디서 왔는지, 어디로 가는지에 대해 장황하게 설명하기 시작합니다. 실제 경험 없이 아이언포지와 카즈 알가르에서 연구한 것임이 분명합니다.>', '', 56647),
(265612, 'koKR', '아라시에 대한 이야기를 들었어요. 국왕으로서... 아니, 호기심이 동했습니다.', '', 56647),
(265403, 'koKR', '우리에게 무슨 말을 하려는 겐가?', '', 56647),
(265214, 'koKR', '흥미롭군요...', '', 56647),
(264962, 'koKR', '사실이라면 직접 보고 싶습니다. 잘아타스와의 싸움에서 동맹으로 포섭할 수도 있겠죠.', '', 56647),
(264692, 'koKR', '용사님! 잿불벌을 몇 마리 풀어줬습니다.', '', 56647),
(264131, 'koKR', '다들 긴장한 것 같지 않습니까? 왜 그런지 알 길이 없군요. \n\n아, 맞다. 무시무시한 파괴의 환영. 그래서 달라란이 살림살이 다 챙겨서 카즈 알가르로 순간이동하는 거였죠. 이제야 기억나네.', '', 56647),
(264128, 'koKR', '카즈 알가르에 도사리는 위험이 걱정되십니까? 걱정 마십쇼. 이 끝내주는 리노 잭슨이 여러분을 지킬 테니까요!', '', 56647),
(264108, 'koKR', '잘아타스를 처치하는 것만으로는 동족을 구할 수 없소. 우리를 몰락으로 이끄는 건 안수레크요.', '', 56647),
(262984, 'koKR', '전령께서 네가 올 거라고 귀띔해 주셨지...', '', 56647),
(262611, 'koKR', '', '전체 시스템... 작동 정지...', 56647),
(261944, 'koKR', '그럴 수 없소. 그러니 내가 해야 하오. 당신은 토석인을 이끌어야 하니까.', '', 56647),
(261934, 'koKR', '지금껏 저 존재들의 영웅담만을 들었는데... 티탄의 계시로다!', '', 56647),
(261921, 'koKR', '너희가 뭐가 필요하든 관심 없다.', '', 56647),
(261418, 'koKR', '', '에헴! 이렇게... 모두 죽었다니까!', 56647),
(261128, 'koKR', '', '드높은 공동의 집정관 겸 고위 증강자 에탁카트라면 연줄을 동원해 내게 승천을 허락해 줄 수 있을 거요.\n\n물론 호의를 얻을 수 있다면 말이지.\n\n<모든 눈을 가늘게 뜨며 은은한 짜증을 표출하는 티시티크>\n\n...찾는 것도 문제긴 하오.', 56647),
(260471, 'koKR', '대강 어림잡아서 말씀해 주실 수 있나요?', '', 56647),
(260469, 'koKR', '', '알 수 없습니다. 기록 보관소에 해당 정보가 저장되어 있지만, 전에 말씀드린 것처럼 작동하지 않습니다.', 56647),
(260334, 'koKR', '열쇠불꽃의 수정을 살펴봤습니다. 아제라이트는 아니지만 상당히 비슷한 게, 서로 연관이 있어 보이더군요.', '', 56647),
(260299, 'koKR', '', '누구나 그런 사연이 하나쯤 있어요. 저도 한 번은 웬 동굴을 발견한 적이 있는데...', 56647),
(260176, 'koKR', '물론이오! 당신 기억도 내 기억과 비슷하겠지. 수천 년이 지나버려 경계 부근이 살짝 희미해지긴 했지만...', '', 56647),
(260092, 'koKR', '', '너희 현상금이 더 커질 때까지 기다리겠다. 그때까지... 등 뒤를 조심하거라.', 56647),
(260028, 'koKR', '앞으로, 그리고 위로. 다음 모험으로 나아가야지.', '', 56647),
(260019, 'koKR', '', '몸이 변했는데... 기분이 어떠세요?', 56647),
(259046, 'koKR', '어둠 속으로 들어가지 마세요.', '어둠 속으로 들어가지 마세요.', 56647),
(258553, 'koKR', '<당신은 그물쥐가 들쳐 올린 쪽지를 유심히 살펴봅니다.>\n\n실패한 실험체들이 지하성채에서 날뛰고 있다. 탈출하기 전에 제거해다오.\n\n주변에 은닉해 둔 페로몬 폭탄이 있으니, 그걸 이용하거라. 그전에 먼저 체취를 가려야 하겠지만 말이야. 페로몬을 선물로 보낼 테니 잘 사용하렴.\n\n장치를 회수해 그 불쌍한 것들에게 안식을 선사해다오.\n\n--방직공', '', 56647),
(258479, 'koKR', '그래! 도망가!', '그래! 도망가!', 56647),
(258194, 'koKR', '여봐라! 다들 각자 근무지로 돌아가라. 얼른!', '', 56647),
(258037, 'koKR', '오해하지 말게. 서둘러 카즈 알가르로 가야 하는 건 사실이야. 근데, 음, 아직 피로가 덜 풀렸어. \n\n아제로스가 마음만 먹으면 정말 엄청난 힘을 발휘해서 말일세.', '', 56647),
(258035, 'koKR', '우리의 운명이 카즈 알가르에 있군요. 무엇이 기다리고 있을까요? 불과 연기 너머에 말이죠.', '', 56647),
(258010, 'koKR', '할아버지는 더 심한 고통도 딛고 일어나셨어요. 금방 깨어나실 거예요.\n\n꼭이요...', '', 56647),
(258006, 'koKR', '이 결과에 아제로스의 책임이 있다고 생각해서는 안 된다고 보네. 마그니는 스스로 내키지 않을 때 연결하는 게 얼마나 위험한지 알고 있었어. \n\n지금으로선 마그니가 어떻게든 아제로스의 전언을 들었길 바랄 수밖에 없어.', '', 56647),
(257697, 'koKR', '진짜 순간이동을 했다고요? 드디어 돌파구를 찾았구나!', '진짜 순간이동을 했다고요? 드디어 돌파구를 찾았구나!', 56647),
(257511, 'koKR', '', '올바리그 님, 어디 계신 거예요? 꼭 필요한 분인데...', 56647),
(255510, 'koKR', '', '잠깐만요! 저 아래 뭐가 있는지 모르잖아요! 지원군이 오는 중이니 기다려도 괜...', 56647),
(254629, 'koKR', '', '이... 어둠은 대체! 너무 강한...!', 56647),
(253162, 'koKR', '더는 초대할 수 없습니다.', '', 56647),
(253151, 'koKR', '격노가 부족합니다.', '', 56647),
(252126, 'koKR', '할아버지가 무사하셔서 정말 다행이에요. 함께 보낸 시간이 많지 않고, 또 할아버지를 떠올릴 때면... \n\n아무튼 이제 괜찮아요! 다 나으신 것 같기도 하고요.', '', 56647),
(268542, 'koKR', '', '네루비안이 소중한 기억 보석을 훔쳐 갔습니다. 상황이 좋지 않지만, 계획이 있습니다.\n\n기억 보석을 유도하는 장치를 만들었습니다. 같이 움직이죠. 이 장치를 사용하세요. 보석을 되찾고 네루비안을 막읍시다.', 56647),
(268257, 'koKR', '굼벵이 고기 삶아 먹은 템퍼 잘못이지.', '', 56647),
(268256, 'koKR', '애초에 방어 담당이 준비하기도 전에 앞서나가서 로브가 더러워진 거잖아.', '', 56647),
(268043, 'koKR', '', '데이, 괜찮아?', 56647),
(267317, 'koKR', '', '<수줍어하던 모습은 온데간데없이 사라지고 숟가락을 칼처럼 휘두르며 즐거워하는 타라>\n\n전 커서 토석인이 되고 싶어요! 엄마가 토석인은 모두 돌이고 안에 보석이 들어 있다고 하셨어요. \n\n전에 보석을 먹어본 적 있는데 꽤 어려웠어요. 그래서 천천히 시작하려고요. 보석을 부수면 더 쉬워질 거예요! 몸이 돌이 되면 좋을 것 같아요. 아무것도 날 해칠 수 없을 테니까요. 아무것도 날 해칠 수 없다면, 뭐든 할 수 있겠죠!', 56647),
(265656, 'koKR', '', '이건... 어떤 기사가 원정을 떠나기 전에 제게 부탁한 일이에요.', 56647),
(265652, 'koKR', '이 조각상은 불꽃 발톱의 일화를 묘사한 겁니다. 불타는 배에서 용감하게 주인을 구한 전설적인 전쟁 스라소니지요.', '', 56647),
(265609, 'koKR', '', '반가워요, 용사님. 이 녀석이 구멍에서 기어 나왔을 때부터 계속 추적해 왔어요.', 56647),
(265317, 'koKR', '와, 제가 똑똑하다고 했다고요? 이런 말 덕분에 제가 계속 머리에 불이 들어오는 거죠. 저질 농담 죄송합니다.', '', 56647),
(264561, 'koKR', '', '괴물은 꽁무니 말고 여왕에게로 돌아갔네. 자네가 얼마나 무서운 영웅인지 여기저기 얘기를 퍼뜨리겠지.', 56647),
(264549, 'koKR', '', '다행히 딸아이와 아이들은 무사하네. 사령관을 약화시키고 가정도 지켰군. 고맙네.', 56647),
(262945, 'koKR', '우린 폭풍이 몰아치는 바다를 가로질렀어. 살면서 그렇게 높은 파도나 강한 바람은 처음이었지! 폭풍에 배가 추락할 거라고 생각한 적도 여러 번 있었어!', '우린 폭풍이 몰아치는 바다를 가로질렀어. 살면서 그렇게 높은 파도나 강한 바람은 처음이었지! 폭풍에 배가 추락할 거라고 생각한 적도 여러 번 있었어!', 56647),
(262812, 'koKR', '안으로 들어가!', '안으로 들어가!', 56647),
(262440, 'koKR', '벌을 내보낼 시간이군!', '', 56647),
(262197, 'koKR', '군침 도는 음식은 아니지만 몇 마리 잡아서 단지에 가두면 훌륭한 조명으로 활용할 수 있어요.\n\n한 번은 잡초를 뒤지는데 웬 커다란 불꽃벌레가 제 단지 조명에 이끌려 나타난 적 있습니다! 꼭 애완동물처럼 제 뒤를 한동안 졸졸 따라다니더군요. 온순한 녀석이었습니다. 그저 윙윙거리며 알록달록한 빛을 발하기만 했죠.', '', 56647),
(261385, 'koKR', '<토석인 인형은 절망이 고스란히 녹아 있습니다. 지상에서 만난 실제 토석인처럼 섬세하고 훌륭한 만듦새가 돋보입니다.\n\n이 작품의 돌 질감은 실제 토석인과 똑같아 보입니다.>', '<토석인 인형은 절망이 고스란히 녹아 있습니다. 지상에서 만난 실제 토석인처럼 섬세하고 훌륭한 만듦새가 돋보입니다.\n\n이 작품의 돌 질감은 실제 토석인과 똑같아 보입니다.>', 56647),
(261292, 'koKR', '멀뚱멀뚱 서 있지 마세요!', '', 56647),
(260817, 'koKR', '어서 와요, $r 친구.\n\n오래전, 의회지기 메릭스 님은 절 도르노갈의 장식가로 임명하셨습니다. \n\n도시의 미적 조화를 유지하는 것이 제 엄숙한 의무입니다. 저는 매 주기 부지런하게 도르노갈 거리에 멋과 아름다움을 엮어 우리의 존귀한 명맥에 걸맞은, 드러날 듯하면서 드러나지 않는 품격과 기능적인 매력을 불어넣고 있습니다. \n\n전속 장식가로서 저는 메릭스 님의 유산을 계승하고 도르노갈이 앞으로도 아름다움과 경이의 등대로 남을 수 있도록 노력할 것을 맹세합니다.\n\n자, 어떻게 도와드릴까요?', '', 56647),
(259422, 'koKR', '', '고맙습니다! 이 장화로 코비스 놈들에게 가만히 마을을 습격하게 내버려두지 않겠다는 걸 보여주세요.', 56647),
(259414, 'koKR', '', '마을을 습격해 유물을 훔친 코비스 무리를 쫓아 구덩이까지 갔습니다.\n\n문제는 제가 전사보다는 발명가에 가깝다는 겁니다. 순전히 아드레날린에 의지해서 여기까지 온 거예요. 하지만 용사님에게 도움이 될 만한 발명품이 있습니다. \n\n내 빛장화를 사용하세요. 이 장화의 마법은 당신을 공중으로 높이 날려 보내 방심한 적에게 내리꽂을 수 있게 해줄 겁니다. 저 아래의 코비스를 물리치는 데 도움이 될 거예요.', 56647),
(257935, 'koKR', '', '네루비안은 스카르딘을 이용해 기계 대변자를 사로잡을 계획입니다.\n\n계획은 있습니다. 이 장치를 가져가세요. 스카르딘을 다른 위치로 유인해 줄 거예요. 그걸로 다른 대변자를 구해주세요. \n\n실험에 가까워... 제가 수행하기엔 부적합하지만요. 전 여기 있겠습니다.', 56647),
(256314, 'koKR', '', '제국 스라소니는 아주 고집이 센 녀석들이에요. 당장 여기 이 불꽃이만 해도 저 말고 다른 사람은 등에 태우려고 들지도 않죠. 그마저도 기분이 안 좋을 때는 저도 한참을 걸어서 배달을 마무리하고요.\n\n그래도 한 번 발동만 걸리면 비행선을 제외하고 불꽃이의 속도를 따라올 게 없을 정도예요. 길에서 믿고 등을 맡기기에 더 좋은 친구도 없고요.', 56647),
(255997, 'koKR', '흥미가 동하네요. 한번 방문해 보고 싶습니다.', '', 56647),
(255898, 'koKR', '<키에라가 미소를 머금고 콧노래를 흥얼거리며 요리를 하고 있습니다. 프라이팬에서 양파와 마늘 냄새가 솔솔 피어납니다.>', '<키에라가 미소를 머금고 콧노래를 흥얼거리며 요리를 하고 있습니다. 프라이팬에서 양파와 마늘 냄새가 솔솔 피어납니다.>', 56647),
(253535, 'koKR', '', '이런, 벌써 가버렸네요. 아까 우릴 구해준 자는 네루비안 편이 아닌 게 확실해요. 그 사람을 찾아보세요. 전 모두를 안전한 곳으로 데려갈게요.', 56647),
(248952, 'koKR', '이거 뛰어야겠는데요!', '', 56647);
