INSERT INTO `faction_locale` (`ID`, `locale`, `Name_lang`, `Description_lang`, `VerifiedBuild`) VALUES
(2640, 'koKR', '브란 브론즈비어드', '믿음직한 구렁 동료', 56647),
(2600, 'koKR', '단절된 실톳', '안수레크 여왕은 위태로운 통치를 펼치고 있으며, 반대 세력도 당연히 존재합니다. 영리한 단절된 실톳은 막후에서 조용히 암약하며 안수레크의 철권통치를 내부에서부터 해체해 나가고 있습니다.', 56647),
(2596, 'koKR', '단절된 실톳 (불멸의 동맹)', '안수레크 여왕은 위태로운 통치를 펼치고 있으며, 반대 세력도 당연히 존재합니다. 영리한 단절된 실톳은 막후에서 조용히 암약하며 안수레크의 철권통치를 내부에서부터 해체해 나가고 있습니다.', 56647),
(2606, 'koKR', '드높은 공동', '실타래의 도시 드높은 공동에 있는 생명체의 행동 양식을 통제합니다.', 56647),
(2649, 'koKR', '장군 (불멸의 동맹)', '아눕아잘은 한때 아즈카헤트에서 가장 이름 높은 군 지휘관이었으나, 안수레크는 그 자리를 자신이 총애하는 승천자에게 넘겨주었습니다. 아눕아잘로서는 절대로 좌시할 수 없는 일입니다.', 56647),
(2648, 'koKR', '방직공 (불멸의 동맹)', '한때 왕실 방직공이었던 미망인 아라크나이는 이제 비판적인 시선으로 옛 고향을 조심스럽게 응시하고 있습니다. 그물쥐와 첩자들로 구성된 연결망 덕택에 아라크나이의 눈이 닿지 않는 사각지대는 없다시피 합니다.', 56647),
(2647, 'koKR', '재상 (불멸의 동맹)', '가장 위험한 위치에 있는 집행관 니즈레크는 안수레크 여왕의 충직한 간언을 올리는 조언자로서 하루하루를 보내고 있습니다. 다행히도 안수레크는 니즈레크가 남는 시간을 여왕의 통치를 끝내는 데 투자하고 있다는 사실을 알지 못하고 있습니다.', 56647),
(2607, 'koKR', '재상', '가장 위험한 위치에 있는 집행관 니즈레크는 안수레크 여왕의 충직한 간언을 올리는 조언자로서 하루하루를 보내고 있습니다. 다행히도 안수레크는 니즈레크가 남는 시간을 여왕의 통치를 끝내는 데 투자하고 있다는 사실을 알지 못하고 있습니다.', 56647),
(2605, 'koKR', '장군', '아눕아잘은 한때 아즈카헤트에서 가장 이름 높은 군 지휘관이었으나, 안수레크는 그 자리를 자신이 총애하는 승천자에게 넘겨주었습니다. 아눕아잘로서는 절대로 좌시할 수 없는 일입니다.', 56647),
(2601, 'koKR', '방직공', '한때 왕실 방직공이었던 미망인 아라크나이는 이제 비판적인 시선으로 옛 고향을 조심스럽게 응시하고 있습니다. 그물쥐와 첩자들로 구성된 연결망 덕택에 아라크나이의 눈이 닿지 않는 사각지대는 없다시피 합니다.', 56647);
