INSERT INTO `scenario_step_locale` (`ID`, `locale`, `Description_lang`, `Title_lang`, `VerifiedBuild`) VALUES
(7726, 'koKR', '시크란은 교활하고 치밀한 전술로 네루비안 군대를 지휘하며, 여왕을 찬탈하려는 침입자를 처단합니다.', '땅거미 성루', 56647),
(7130, 'koKR', '도르닉을 차원문으로 끌고 가 영원히 섬에서 추방해야 합니다!', '종막: 도르닉의 최후', 56647),
(7129, 'koKR', '수호자가 토석인들에게 도르닉에 대한 저항을 허락했습니다.', '3막: 수호자의 심판', 56647),
(7128, 'koKR', '도르닉이 토석인을 잔혹하게 핍박하고 있습니다! 보주에 감전되지 않도록 주의해야 합니다.', '2막: 도르닉 잔혹사', 56647),
(7127, 'koKR', '토석인의 새로운 감시자, 도르닉의 도착을 축하해야 합니다.', '1막: 수호자의 선물 도르닉', 56647),
(6989, 'koKR', '꼭두각시를 구출해야 합니다.', '나선의 방직소', 56647),
